CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(24) NOT NULL CHECK (role IN ('CUSTOMER','RESTAURANT','RIDER','ADMIN')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refresh_sessions (id BIGSERIAL PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX refresh_sessions_user_idx ON refresh_sessions(user_id);
CREATE TABLE districts (id BIGSERIAL PRIMARY KEY, name VARCHAR(80) NOT NULL, division VARCHAR(80) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(name, division));
CREATE TABLE delivery_coverage (id BIGSERIAL PRIMARY KEY, district_id BIGINT NOT NULL REFERENCES districts(id), city VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, delivery_fee NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(delivery_fee>=0), UNIQUE(district_id,city));
CREATE TABLE restaurants (id BIGSERIAL PRIMARY KEY,name_en VARCHAR(160) NOT NULL,name_bn VARCHAR(160),district_id BIGINT NOT NULL REFERENCES districts(id),city VARCHAR(100) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE menu_items (id BIGSERIAL PRIMARY KEY,restaurant_id BIGINT NOT NULL REFERENCES restaurants(id),name_en VARCHAR(160) NOT NULL,name_bn VARCHAR(160),price NUMERIC(10,2) NOT NULL CHECK(price>0),available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE customer_orders (id BIGSERIAL PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES users(id),restaurant_id BIGINT NOT NULL REFERENCES restaurants(id),status VARCHAR(24) NOT NULL DEFAULT 'PENDING',payment_method VARCHAR(16) NOT NULL CHECK(payment_method='COD'),subtotal NUMERIC(10,2) NOT NULL CHECK(subtotal>=0),delivery_fee NUMERIC(10,2) NOT NULL CHECK(delivery_fee>=0),district VARCHAR(80) NOT NULL,city VARCHAR(100) NOT NULL,address TEXT NOT NULL,phone VARCHAR(24) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_orders(id) ON DELETE CASCADE,menu_item_id BIGINT NOT NULL REFERENCES menu_items(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 50),unit_price NUMERIC(10,2) NOT NULL CHECK(unit_price>0));
CREATE TABLE order_status_events (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_orders(id) ON DELETE CASCADE,status VARCHAR(24) NOT NULL,actor_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
